/** `minute`'a kadarki demo kareleri (son 3 dk penceresi; en az son kare). */
export function demoTrackingWindow(minute: number): TrackingFrame[] {
  const upTo = DEMO_TRACKING_FRAMES.filter((f) => f.minute <= minute);
  if (upTo.length === 0) return [];
  const last = upTo[upTo.length - 1];
  const win = upTo.filter((f) => f.minute >= last.minute - 3);
  return win.length ? win : [last];
}
